-- 365: Original BrillaPrep WASSCE Integrated Science Paper 2 theory practice paper (2024 format).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_365_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_365_guard;
INSERT INTO _migration_365_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM past_papers p WHERE p.id = 'pp_wassce_sci_2024_2' AND NOT (p.id IS 'pp_wassce_sci_2024_2' AND p.exam_type_id IS 'exam_wassce' AND p.subject_id IS 'subj_wassce_int_science' AND p.paper_type_id IS 'paper_wassce_2' AND p.year IS '2024' AND p.month IS 'May-June' AND p.series IS 'WASSCE' AND p.title IS 'Integrated Science Paper 2 (2024)' AND p.description IS 'WASSCE Integrated Science theory practice: compulsory structured questions and essays across the syllabus strands.' AND p.total_questions IS '8' AND p.total_marks IS '100' AND p.time_allowed IS '105' AND p.instructions IS 'Answer ALL the questions in this paper.' AND p.is_complete IS '1' AND p.is_premium IS '0' AND p.source_url IS NULL)) THEN 1 ELSE 0 END;
INSERT INTO _migration_365_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_sci_2024_2_001' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_eco' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_sci_2024_2' AND q.question_text IS 'A maize farm supports grasshoppers, lizards, hawks and earthworms alongside the maize plants.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) An ecosystem is a community of living organisms interacting with one another and with their non-living (physical) environment as a functional unit. (b) Producer: maize plants. Consumers: grasshopper (primary), lizard and hawk (secondary). (c) Maize → grasshopper → lizard → hawk (any three-linked correct sequence earns full marks). (d) Lizards and hawks would lose a food source and decline, while maize yield would rise without the pest; the food chain would be disrupted.' AND q.explanation IS '(a) An ecosystem is a community of living organisms interacting with one another and with their non-living (physical) environment as a functional unit. (b) Producer: maize plants. Consumers: grasshopper (primary), lizard and hawk (secondary). (c) Maize → grasshopper → lizard → hawk (any three-linked correct sequence earns full marks). (d) Lizards and hawks would lose a food source and decline, while maize yield would rise without the pest; the food chain would be disrupted.' AND q.difficulty IS 'medium' AND q.points IS '12' AND q.marks IS '12' AND q.time_limit IS NULL AND q.question_number IS '1' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_sci_2024_2_001' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_001_a' AND NOT (sp.question_id IS 'q_sci_2024_2_001' AND sp.part_label IS 'a' AND sp.part_text IS 'Define the term ecosystem.' AND sp.marks IS 3 AND sp.correct_answer IS 'An ecosystem is a community of living organisms interacting with one another and with their non-living (physical) environment as a functional unit.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_001_b' AND NOT (sp.question_id IS 'q_sci_2024_2_001' AND sp.part_label IS 'b' AND sp.part_text IS 'Identify the producer and two primary or secondary consumers in the farm community.' AND sp.marks IS 3 AND sp.correct_answer IS 'Producer: maize plants. Consumers: grasshopper (primary), lizard and hawk (secondary).')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_001_c' AND NOT (sp.question_id IS 'q_sci_2024_2_001' AND sp.part_label IS 'c' AND sp.part_text IS 'Construct a food chain using three of the organisms named above.' AND sp.marks IS 3 AND sp.correct_answer IS 'Maize → grasshopper → lizard → hawk (any three-linked correct sequence earns full marks).')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_001_d' AND NOT (sp.question_id IS 'q_sci_2024_2_001' AND sp.part_label IS 'd' AND sp.part_text IS 'State and explain one effect on the ecosystem if all the grasshoppers were removed.' AND sp.marks IS 3 AND sp.correct_answer IS 'Lizards and hawks would lose a food source and decline, while maize yield would rise without the pest; the food chain would be disrupted.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_365_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_sci_2024_2_002' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_mat' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_sci_2024_2' AND q.question_text IS 'A mixture contains iron filings, sand and common salt.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Pass a magnet over or through the mixture; the iron filings are attracted to the magnet, leaving sand and salt behind. (b) Add water and stir to dissolve the salt, filter to remove the sand, then evaporate (or crystallise) the filtrate to obtain pure salt. (c) Dissolved salt particles are too small and pass through the pores of filter paper with the water; only insoluble solids are trapped. (d) Distillation: the water is evaporated and then condensed back to pure liquid, leaving the salt behind.' AND q.explanation IS '(a) Pass a magnet over or through the mixture; the iron filings are attracted to the magnet, leaving sand and salt behind. (b) Add water and stir to dissolve the salt, filter to remove the sand, then evaporate (or crystallise) the filtrate to obtain pure salt. (c) Dissolved salt particles are too small and pass through the pores of filter paper with the water; only insoluble solids are trapped. (d) Distillation: the water is evaporated and then condensed back to pure liquid, leaving the salt behind.' AND q.difficulty IS 'medium' AND q.points IS '12' AND q.marks IS '12' AND q.time_limit IS NULL AND q.question_number IS '2' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Describe' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_sci_2024_2_002' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_002_a' AND NOT (sp.question_id IS 'q_sci_2024_2_002' AND sp.part_label IS 'a' AND sp.part_text IS 'Describe how the iron filings can be separated from the mixture.' AND sp.marks IS 3 AND sp.correct_answer IS 'Pass a magnet over or through the mixture; the iron filings are attracted to the magnet, leaving sand and salt behind.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_002_b' AND NOT (sp.question_id IS 'q_sci_2024_2_002' AND sp.part_label IS 'b' AND sp.part_text IS 'Outline the steps you would use to obtain pure salt from the remaining mixture.' AND sp.marks IS 3 AND sp.correct_answer IS 'Add water and stir to dissolve the salt, filter to remove the sand, then evaporate (or crystallise) the filtrate to obtain pure salt.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_002_c' AND NOT (sp.question_id IS 'q_sci_2024_2_002' AND sp.part_label IS 'c' AND sp.part_text IS 'Explain why filtration alone cannot separate the dissolved salt from the water.' AND sp.marks IS 3 AND sp.correct_answer IS 'Dissolved salt particles are too small and pass through the pores of filter paper with the water; only insoluble solids are trapped.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_002_d' AND NOT (sp.question_id IS 'q_sci_2024_2_002' AND sp.part_label IS 'd' AND sp.part_text IS 'Name the process you would use to recover pure water from the salt solution.' AND sp.marks IS 3 AND sp.correct_answer IS 'Distillation: the water is evaporated and then condensed back to pure liquid, leaving the salt behind.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_365_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_sci_2024_2_003' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_enr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_sci_2024_2' AND q.question_text IS 'A student connects a battery and two identical lamps in series to form a closed circuit.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Battery (supplies electrical energy), connecting wires (carry current), lamps (convert electrical energy to light), and a switch (opens or closes the circuit). (b) There is only one path for the charge to flow, so the same quantity of charge passes every point per second. (c) The lamps become dimmer because total resistance increases, so the current through each lamp decreases. (d) In series, resistances add: R = 4 + 4 + 4 = 12 Ω.' AND q.explanation IS '(a) Battery (supplies electrical energy), connecting wires (carry current), lamps (convert electrical energy to light), and a switch (opens or closes the circuit). (b) There is only one path for the charge to flow, so the same quantity of charge passes every point per second. (c) The lamps become dimmer because total resistance increases, so the current through each lamp decreases. (d) In series, resistances add: R = 4 + 4 + 4 = 12 Ω.' AND q.difficulty IS 'medium' AND q.points IS '12' AND q.marks IS '12' AND q.time_limit IS NULL AND q.question_number IS '3' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_sci_2024_2_003' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_003_a' AND NOT (sp.question_id IS 'q_sci_2024_2_003' AND sp.part_label IS 'a' AND sp.part_text IS 'List the components needed for the circuit and state the function of each.' AND sp.marks IS 3 AND sp.correct_answer IS 'Battery (supplies electrical energy), connecting wires (carry current), lamps (convert electrical energy to light), and a switch (opens or closes the circuit).')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_003_b' AND NOT (sp.question_id IS 'q_sci_2024_2_003' AND sp.part_label IS 'b' AND sp.part_text IS 'Explain why the current is the same at every point in a series circuit.' AND sp.marks IS 3 AND sp.correct_answer IS 'There is only one path for the charge to flow, so the same quantity of charge passes every point per second.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_003_c' AND NOT (sp.question_id IS 'q_sci_2024_2_003' AND sp.part_label IS 'c' AND sp.part_text IS 'State and explain what happens to the brightness of the lamps when a third identical lamp is added in series.' AND sp.marks IS 3 AND sp.correct_answer IS 'The lamps become dimmer because total resistance increases, so the current through each lamp decreases.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_003_d' AND NOT (sp.question_id IS 'q_sci_2024_2_003' AND sp.part_label IS 'd' AND sp.part_text IS 'If each lamp has a resistance of 4 Ω, calculate the total resistance when three lamps are connected in series.' AND sp.marks IS 3 AND sp.correct_answer IS 'In series, resistances add: R = 4 + 4 + 4 = 12 Ω.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_365_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_sci_2024_2_004' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_bio' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_sci_2024_2' AND q.question_text IS 'A meal of kenkey and fried fish is eaten by a student.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Digestion is the breakdown of large, insoluble food molecules into smaller, soluble molecules that can be absorbed into the bloodstream. (b) Salivary amylase (ptyalin), which acts on starch, breaking it down to maltose. (c) Protein digestion begins in the stomach, where pepsin breaks proteins into peptides in the presence of hydrochloric acid. (d) Its inner wall is folded into millions of villi (with microvilli), giving a very large surface area, and each villus has a rich blood supply and thin walls for fast diffusion.' AND q.explanation IS '(a) Digestion is the breakdown of large, insoluble food molecules into smaller, soluble molecules that can be absorbed into the bloodstream. (b) Salivary amylase (ptyalin), which acts on starch, breaking it down to maltose. (c) Protein digestion begins in the stomach, where pepsin breaks proteins into peptides in the presence of hydrochloric acid. (d) Its inner wall is folded into millions of villi (with microvilli), giving a very large surface area, and each villus has a rich blood supply and thin walls for fast diffusion.' AND q.difficulty IS 'medium' AND q.points IS '12' AND q.marks IS '12' AND q.time_limit IS NULL AND q.question_number IS '4' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_sci_2024_2_004' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_004_a' AND NOT (sp.question_id IS 'q_sci_2024_2_004' AND sp.part_label IS 'a' AND sp.part_text IS 'Define digestion.' AND sp.marks IS 3 AND sp.correct_answer IS 'Digestion is the breakdown of large, insoluble food molecules into smaller, soluble molecules that can be absorbed into the bloodstream.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_004_b' AND NOT (sp.question_id IS 'q_sci_2024_2_004' AND sp.part_label IS 'b' AND sp.part_text IS 'Name the enzyme in saliva and the food substance it acts upon.' AND sp.marks IS 3 AND sp.correct_answer IS 'Salivary amylase (ptyalin), which acts on starch, breaking it down to maltose.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_004_c' AND NOT (sp.question_id IS 'q_sci_2024_2_004' AND sp.part_label IS 'c' AND sp.part_text IS 'State where the digestion of the protein in the fish begins and name the enzyme involved.' AND sp.marks IS 3 AND sp.correct_answer IS 'Protein digestion begins in the stomach, where pepsin breaks proteins into peptides in the presence of hydrochloric acid.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_004_d' AND NOT (sp.question_id IS 'q_sci_2024_2_004' AND sp.part_label IS 'd' AND sp.part_text IS 'Explain one way in which the small intestine is adapted for absorption of the digested food.' AND sp.marks IS 3 AND sp.correct_answer IS 'Its inner wall is folded into millions of villi (with microvilli), giving a very large surface area, and each villus has a rich blood supply and thin walls for fast diffusion.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_365_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_sci_2024_2_005' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_agr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_sci_2024_2' AND q.question_text IS 'A farmer wants to improve a patch of land before planting maize.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Mineral particles (anchor roots and supply nutrients) and humus/organic matter (holds moisture and releases nutrients); air and water in the pores support root respiration and nutrient uptake. (b) Loam balances sand, silt and clay with humus, so it drains well yet retains enough water and nutrients, and it is easily worked by roots and tools. (c) Compost adds humus, which improves soil structure and water retention and releases nitrogen, phosphorus and potassium slowly as it decomposes. (d) Contour ploughing (or terracing): ploughing across the slope slows run-off, reducing soil erosion and keeping nutrients in place.' AND q.explanation IS '(a) Mineral particles (anchor roots and supply nutrients) and humus/organic matter (holds moisture and releases nutrients); air and water in the pores support root respiration and nutrient uptake. (b) Loam balances sand, silt and clay with humus, so it drains well yet retains enough water and nutrients, and it is easily worked by roots and tools. (c) Compost adds humus, which improves soil structure and water retention and releases nitrogen, phosphorus and potassium slowly as it decomposes. (d) Contour ploughing (or terracing): ploughing across the slope slows run-off, reducing soil erosion and keeping nutrients in place.' AND q.difficulty IS 'medium' AND q.points IS '12' AND q.marks IS '12' AND q.time_limit IS NULL AND q.question_number IS '5' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_sci_2024_2_005' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_005_a' AND NOT (sp.question_id IS 'q_sci_2024_2_005' AND sp.part_label IS 'a' AND sp.part_text IS 'Name two components of soil and state the importance of each to plant growth.' AND sp.marks IS 3 AND sp.correct_answer IS 'Mineral particles (anchor roots and supply nutrients) and humus/organic matter (holds moisture and releases nutrients); air and water in the pores support root respiration and nutrient uptake.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_005_b' AND NOT (sp.question_id IS 'q_sci_2024_2_005' AND sp.part_label IS 'b' AND sp.part_text IS 'Explain why loamy soil is considered best for crop production.' AND sp.marks IS 3 AND sp.correct_answer IS 'Loam balances sand, silt and clay with humus, so it drains well yet retains enough water and nutrients, and it is easily worked by roots and tools.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_005_c' AND NOT (sp.question_id IS 'q_sci_2024_2_005' AND sp.part_label IS 'c' AND sp.part_text IS 'Describe how adding compost improves the soil.' AND sp.marks IS 3 AND sp.correct_answer IS 'Compost adds humus, which improves soil structure and water retention and releases nitrogen, phosphorus and potassium slowly as it decomposes.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_005_d' AND NOT (sp.question_id IS 'q_sci_2024_2_005' AND sp.part_label IS 'd' AND sp.part_text IS 'State one soil conservation practice the farmer can use on sloping land and explain how it works.' AND sp.marks IS 3 AND sp.correct_answer IS 'Contour ploughing (or terracing): ploughing across the slope slows run-off, reducing soil erosion and keeping nutrients in place.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_365_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_sci_2024_2_006' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_hlt' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_sci_2024_2' AND q.question_text IS 'Malaria remains a common illness in many Ghanaian communities.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Malaria is caused by Plasmodium parasites and transmitted by the female Anopheles mosquito. (b) Any two of: high fever with chills, headache, sweating, nausea/vomiting, body weakness. (c) Sleeping under insecticide-treated mosquito nets, and clearing stagnant water or spraying insecticides to kill mosquitoes and larvae. (d) Mosquitoes breed in stagnant water; removing it destroys breeding sites, so fewer adult mosquitoes emerge to transmit the parasite.' AND q.explanation IS '(a) Malaria is caused by Plasmodium parasites and transmitted by the female Anopheles mosquito. (b) Any two of: high fever with chills, headache, sweating, nausea/vomiting, body weakness. (c) Sleeping under insecticide-treated mosquito nets, and clearing stagnant water or spraying insecticides to kill mosquitoes and larvae. (d) Mosquitoes breed in stagnant water; removing it destroys breeding sites, so fewer adult mosquitoes emerge to transmit the parasite.' AND q.difficulty IS 'medium' AND q.points IS '12' AND q.marks IS '12' AND q.time_limit IS NULL AND q.question_number IS '6' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_sci_2024_2_006' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_006_a' AND NOT (sp.question_id IS 'q_sci_2024_2_006' AND sp.part_label IS 'a' AND sp.part_text IS 'Name the organism that causes malaria and the vector that transmits it.' AND sp.marks IS 3 AND sp.correct_answer IS 'Malaria is caused by Plasmodium parasites and transmitted by the female Anopheles mosquito.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_006_b' AND NOT (sp.question_id IS 'q_sci_2024_2_006' AND sp.part_label IS 'b' AND sp.part_text IS 'State two symptoms of malaria.' AND sp.marks IS 3 AND sp.correct_answer IS 'Any two of: high fever with chills, headache, sweating, nausea/vomiting, body weakness.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_006_c' AND NOT (sp.question_id IS 'q_sci_2024_2_006' AND sp.part_label IS 'c' AND sp.part_text IS 'Describe two measures used to prevent the spread of malaria.' AND sp.marks IS 3 AND sp.correct_answer IS 'Sleeping under insecticide-treated mosquito nets, and clearing stagnant water or spraying insecticides to kill mosquitoes and larvae.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_sci_2024_2_006_d' AND NOT (sp.question_id IS 'q_sci_2024_2_006' AND sp.part_label IS 'd' AND sp.part_text IS 'Explain why draining stagnant water helps to control malaria.' AND sp.marks IS 3 AND sp.correct_answer IS 'Mosquitoes breed in stagnant water; removing it destroys breeding sites, so fewer adult mosquitoes emerge to transmit the parasite.')) THEN 1 ELSE 0 END;
