INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_sci_2024_2_001', 'topic_wassce_p2_sci_eco', 'subj_wassce_int_science', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_sci_2024_2', 'A maize farm supports grasshoppers, lizards, hawks and earthworms alongside the maize plants.', 'structured', NULL, NULL, '(a) An ecosystem is a community of living organisms interacting with one another and with their non-living (physical) environment as a functional unit. (b) Producer: maize plants. Consumers: grasshopper (primary), lizard and hawk (secondary). (c) Maize → grasshopper → lizard → hawk (any three-linked correct sequence earns full marks). (d) Lizards and hawks would lose a food source and decline, while maize yield would rise without the pest; the food chain would be disrupted.', '(a) An ecosystem is a community of living organisms interacting with one another and with their non-living (physical) environment as a functional unit. (b) Producer: maize plants. Consumers: grasshopper (primary), lizard and hawk (secondary). (c) Maize → grasshopper → lizard → hawk (any three-linked correct sequence earns full marks). (d) Lizards and hawks would lose a food source and decline, while maize yield would rise without the pest; the food chain would be disrupted.', 'medium', '12', '12', NULL, '1', 'A', '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_sci_2024_2_002', 'topic_wassce_p2_sci_mat', 'subj_wassce_int_science', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_sci_2024_2', 'A mixture contains iron filings, sand and common salt.', 'structured', NULL, NULL, '(a) Pass a magnet over or through the mixture; the iron filings are attracted to the magnet, leaving sand and salt behind. (b) Add water and stir to dissolve the salt, filter to remove the sand, then evaporate (or crystallise) the filtrate to obtain pure salt. (c) Dissolved salt particles are too small and pass through the pores of filter paper with the water; only insoluble solids are trapped. (d) Distillation: the water is evaporated and then condensed back to pure liquid, leaving the salt behind.', '(a) Pass a magnet over or through the mixture; the iron filings are attracted to the magnet, leaving sand and salt behind. (b) Add water and stir to dissolve the salt, filter to remove the sand, then evaporate (or crystallise) the filtrate to obtain pure salt. (c) Dissolved salt particles are too small and pass through the pores of filter paper with the water; only insoluble solids are trapped. (d) Distillation: the water is evaporated and then condensed back to pure liquid, leaving the salt behind.', 'medium', '12', '12', NULL, '2', 'A', '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_sci_2024_2_003', 'topic_wassce_p2_sci_enr', 'subj_wassce_int_science', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_sci_2024_2', 'A student connects a battery and two identical lamps in series to form a closed circuit.', 'structured', NULL, NULL, '(a) Battery (supplies electrical energy), connecting wires (carry current), lamps (convert electrical energy to light), and a switch (opens or closes the circuit). (b) There is only one path for the charge to flow, so the same quantity of charge passes every point per second. (c) The lamps become dimmer because total resistance increases, so the current through each lamp decreases. (d) In series, resistances add: R = 4 + 4 + 4 = 12 Ω.', '(a) Battery (supplies electrical energy), connecting wires (carry current), lamps (convert electrical energy to light), and a switch (opens or closes the circuit). (b) There is only one path for the charge to flow, so the same quantity of charge passes every point per second. (c) The lamps become dimmer because total resistance increases, so the current through each lamp decreases. (d) In series, resistances add: R = 4 + 4 + 4 = 12 Ω.', 'medium', '12', '12', NULL, '3', 'A', '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_sci_2024_2_004', 'topic_wassce_p2_sci_bio', 'subj_wassce_int_science', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_sci_2024_2', 'A meal of kenkey and fried fish is eaten by a student.', 'structured', NULL, NULL, '(a) Digestion is the breakdown of large, insoluble food molecules into smaller, soluble molecules that can be absorbed into the bloodstream. (b) Salivary amylase (ptyalin), which acts on starch, breaking it down to maltose. (c) Protein digestion begins in the stomach, where pepsin breaks proteins into peptides in the presence of hydrochloric acid. (d) Its inner wall is folded into millions of villi (with microvilli), giving a very large surface area, and each villus has a rich blood supply and thin walls for fast diffusion.', '(a) Digestion is the breakdown of large, insoluble food molecules into smaller, soluble molecules that can be absorbed into the bloodstream. (b) Salivary amylase (ptyalin), which acts on starch, breaking it down to maltose. (c) Protein digestion begins in the stomach, where pepsin breaks proteins into peptides in the presence of hydrochloric acid. (d) Its inner wall is folded into millions of villi (with microvilli), giving a very large surface area, and each villus has a rich blood supply and thin walls for fast diffusion.', 'medium', '12', '12', NULL, '4', 'A', '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_sci_2024_2_005', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_sci_2024_2', 'A farmer wants to improve a patch of land before planting maize.', 'structured', NULL, NULL, '(a) Mineral particles (anchor roots and supply nutrients) and humus/organic matter (holds moisture and releases nutrients); air and water in the pores support root respiration and nutrient uptake. (b) Loam balances sand, silt and clay with humus, so it drains well yet retains enough water and nutrients, and it is easily worked by roots and tools. (c) Compost adds humus, which improves soil structure and water retention and releases nitrogen, phosphorus and potassium slowly as it decomposes. (d) Contour ploughing (or terracing): ploughing across the slope slows run-off, reducing soil erosion and keeping nutrients in place.', '(a) Mineral particles (anchor roots and supply nutrients) and humus/organic matter (holds moisture and releases nutrients); air and water in the pores support root respiration and nutrient uptake. (b) Loam balances sand, silt and clay with humus, so it drains well yet retains enough water and nutrients, and it is easily worked by roots and tools. (c) Compost adds humus, which improves soil structure and water retention and releases nitrogen, phosphorus and potassium slowly as it decomposes. (d) Contour ploughing (or terracing): ploughing across the slope slows run-off, reducing soil erosion and keeping nutrients in place.', 'medium', '12', '12', NULL, '5', 'A', '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_sci_2024_2_006', 'topic_wassce_p2_sci_hlt', 'subj_wassce_int_science', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_sci_2024_2', 'Malaria remains a common illness in many Ghanaian communities.', 'structured', NULL, NULL, '(a) Malaria is caused by Plasmodium parasites and transmitted by the female Anopheles mosquito. (b) Any two of: high fever with chills, headache, sweating, nausea/vomiting, body weakness. (c) Sleeping under insecticide-treated mosquito nets, and clearing stagnant water or spraying insecticides to kill mosquitoes and larvae. (d) Mosquitoes breed in stagnant water; removing it destroys breeding sites, so fewer adult mosquitoes emerge to transmit the parasite.', '(a) Malaria is caused by Plasmodium parasites and transmitted by the female Anopheles mosquito. (b) Any two of: high fever with chills, headache, sweating, nausea/vomiting, body weakness. (c) Sleeping under insecticide-treated mosquito nets, and clearing stagnant water or spraying insecticides to kill mosquitoes and larvae. (d) Mosquitoes breed in stagnant water; removing it destroys breeding sites, so fewer adult mosquitoes emerge to transmit the parasite.', 'medium', '12', '12', NULL, '6', 'A', '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_sci_2024_2_007', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_sci_2024_2', 'Your community is facing a waste disposal crisis. Discuss four proper methods of managing solid waste in your community, giving one advantage and one limitation of each method.', 'essay', NULL, NULL, 'A strong answer discusses four of: sanitary landfilling (advantage: handles large mixed volumes cheaply; limitation: needs land and can pollute groundwater if unlined), composting of organic waste (advantage: produces manure and reduces refuse volume; limitation: only organic fraction and needs sorting), recycling and reuse (advantage: conserves raw materials and creates income; limitation: requires separation at source and markets for recyclables), and controlled incineration (advantage: greatly reduces volume and destroys pathogens; limitation: smoke and air pollution, high cost). Each method is described clearly, and one advantage and one limitation are explicitly tied to community conditions such as cost, land or labour.', 'A strong answer discusses four of: sanitary landfilling (advantage: handles large mixed volumes cheaply; limitation: needs land and can pollute groundwater if unlined), composting of organic waste (advantage: produces manure and reduces refuse volume; limitation: only organic fraction and needs sorting), recycling and reuse (advantage: conserves raw materials and creates income; limitation: requires separation at source and markets for recyclables), and controlled incineration (advantage: greatly reduces volume and destroys pathogens; limitation: smoke and air pollution, high cost). Each method is described clearly, and one advantage and one limitation are explicitly tied to community conditions such as cost, land or labour.', 'medium', '14', '14', NULL, '7', 'B', '1', NULL, NULL, 'Discuss', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_sci_2024_2_008', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_sci_2024_2', 'Discuss the causes and effects of water pollution in Ghanaian communities and suggest two measures that can be taken to control it.', 'essay', NULL, NULL, 'A strong answer names causes such as dumping of refuse and sewage into streams, chemical fertiliser and pesticide run-off from farms, illegal mining (galamsey) washing mercury and silt into rivers, and oil or soapy water from washing at riverbanks. Effects include water-borne diseases such as cholera and typhoid, death of fish and other aquatic life as oxygen levels fall, siltation that raises the cost of treating pipe-borne water, and loss of fishing livelihoods. Control measures: enforcing by-laws and pollution penalties with regular monitoring of water bodies, and educating communities while providing proper refuse collection so waste is not dumped into rivers; buffer-zone tree planting along riverbanks is also creditable.', 'A strong answer names causes such as dumping of refuse and sewage into streams, chemical fertiliser and pesticide run-off from farms, illegal mining (galamsey) washing mercury and silt into rivers, and oil or soapy water from washing at riverbanks. Effects include water-borne diseases such as cholera and typhoid, death of fish and other aquatic life as oxygen levels fall, siltation that raises the cost of treating pipe-borne water, and loss of fishing livelihoods. Control measures: enforcing by-laws and pollution penalties with regular monitoring of water bodies, and educating communities while providing proper refuse collection so waste is not dumped into rivers; buffer-zone tree planting along riverbanks is also creditable.', 'medium', '14', '14', NULL, '8', 'B', '1', NULL, NULL, 'Discuss', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_sci_2024_2_007', 'q_sci_2024_2_007', '150', '400', '1', '1', '{"points":[{"point":"Identifies four appropriate solid-waste management methods","marks":4},{"point":"Explains a correct advantage of each method","marks":5},{"point":"Explains a correct limitation of each method","marks":5}]}', 'A strong answer discusses four of: sanitary landfilling (advantage: handles large mixed volumes cheaply; limitation: needs land and can pollute groundwater if unlined), composting of organic waste (advantage: produces manure and reduces refuse volume; limitation: only organic fraction and needs sorting), recycling and reuse (advantage: conserves raw materials and creates income; limitation: requires separation at source and markets for recyclables), and controlled incineration (advantage: greatly reduces volume and destroys pathogens; limitation: smoke and air pollution, high cost). Each method is described clearly, and one advantage and one limitation are explicitly tied to community conditions such as cost, land or labour.', NULL, '["Four distinct waste management methods correctly described","One advantage stated for each method","One limitation stated for each method"]', '["Reference to community-level cost or labour constraints","A concluding recommendation of the most suitable mix of methods"]', '1');
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_sci_2024_2_008', 'q_sci_2024_2_008', '150', '400', '1', '1', '{"points":[{"point":"Explains at least three causes of water pollution","marks":4},{"point":"Explains at least three effects on health, aquatic life or livelihoods","marks":5},{"point":"Suggests two workable control measures","marks":5}]}', 'A strong answer names causes such as dumping of refuse and sewage into streams, chemical fertiliser and pesticide run-off from farms, illegal mining (galamsey) washing mercury and silt into rivers, and oil or soapy water from washing at riverbanks. Effects include water-borne diseases such as cholera and typhoid, death of fish and other aquatic life as oxygen levels fall, siltation that raises the cost of treating pipe-borne water, and loss of fishing livelihoods. Control measures: enforcing by-laws and pollution penalties with regular monitoring of water bodies, and educating communities while providing proper refuse collection so waste is not dumped into rivers; buffer-zone tree planting along riverbanks is also creditable.', NULL, '["At least three distinct causes explained","At least three distinct effects explained","Two practical control measures suggested"]', '["Named Ghanaian context such as galamsey-affected rivers","Links between cause, effect and chosen control measure"]', '1');
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_001_a', 'q_sci_2024_2_001', 'a', 'Define the term ecosystem.', 3, 'An ecosystem is a community of living organisms interacting with one another and with their non-living (physical) environment as a functional unit.', NULL, 'text', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_001_b', 'q_sci_2024_2_001', 'b', 'Identify the producer and two primary or secondary consumers in the farm community.', 3, 'Producer: maize plants. Consumers: grasshopper (primary), lizard and hawk (secondary).', NULL, 'text', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_001_c', 'q_sci_2024_2_001', 'c', 'Construct a food chain using three of the organisms named above.', 3, 'Maize → grasshopper → lizard → hawk (any three-linked correct sequence earns full marks).', NULL, 'text', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_001_d', 'q_sci_2024_2_001', 'd', 'State and explain one effect on the ecosystem if all the grasshoppers were removed.', 3, 'Lizards and hawks would lose a food source and decline, while maize yield would rise without the pest; the food chain would be disrupted.', NULL, 'text', 4);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_002_a', 'q_sci_2024_2_002', 'a', 'Describe how the iron filings can be separated from the mixture.', 3, 'Pass a magnet over or through the mixture; the iron filings are attracted to the magnet, leaving sand and salt behind.', NULL, 'text', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_002_b', 'q_sci_2024_2_002', 'b', 'Outline the steps you would use to obtain pure salt from the remaining mixture.', 3, 'Add water and stir to dissolve the salt, filter to remove the sand, then evaporate (or crystallise) the filtrate to obtain pure salt.', NULL, 'text', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_002_c', 'q_sci_2024_2_002', 'c', 'Explain why filtration alone cannot separate the dissolved salt from the water.', 3, 'Dissolved salt particles are too small and pass through the pores of filter paper with the water; only insoluble solids are trapped.', NULL, 'text', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_002_d', 'q_sci_2024_2_002', 'd', 'Name the process you would use to recover pure water from the salt solution.', 3, 'Distillation: the water is evaporated and then condensed back to pure liquid, leaving the salt behind.', NULL, 'text', 4);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_003_a', 'q_sci_2024_2_003', 'a', 'List the components needed for the circuit and state the function of each.', 3, 'Battery (supplies electrical energy), connecting wires (carry current), lamps (convert electrical energy to light), and a switch (opens or closes the circuit).', NULL, 'text', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_003_b', 'q_sci_2024_2_003', 'b', 'Explain why the current is the same at every point in a series circuit.', 3, 'There is only one path for the charge to flow, so the same quantity of charge passes every point per second.', NULL, 'text', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_003_c', 'q_sci_2024_2_003', 'c', 'State and explain what happens to the brightness of the lamps when a third identical lamp is added in series.', 3, 'The lamps become dimmer because total resistance increases, so the current through each lamp decreases.', NULL, 'text', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_003_d', 'q_sci_2024_2_003', 'd', 'If each lamp has a resistance of 4 Ω, calculate the total resistance when three lamps are connected in series.', 3, 'In series, resistances add: R = 4 + 4 + 4 = 12 Ω.', NULL, 'text', 4);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_004_a', 'q_sci_2024_2_004', 'a', 'Define digestion.', 3, 'Digestion is the breakdown of large, insoluble food molecules into smaller, soluble molecules that can be absorbed into the bloodstream.', NULL, 'text', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_004_b', 'q_sci_2024_2_004', 'b', 'Name the enzyme in saliva and the food substance it acts upon.', 3, 'Salivary amylase (ptyalin), which acts on starch, breaking it down to maltose.', NULL, 'text', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_004_c', 'q_sci_2024_2_004', 'c', 'State where the digestion of the protein in the fish begins and name the enzyme involved.', 3, 'Protein digestion begins in the stomach, where pepsin breaks proteins into peptides in the presence of hydrochloric acid.', NULL, 'text', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_004_d', 'q_sci_2024_2_004', 'd', 'Explain one way in which the small intestine is adapted for absorption of the digested food.', 3, 'Its inner wall is folded into millions of villi (with microvilli), giving a very large surface area, and each villus has a rich blood supply and thin walls for fast diffusion.', NULL, 'text', 4);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_005_a', 'q_sci_2024_2_005', 'a', 'Name two components of soil and state the importance of each to plant growth.', 3, 'Mineral particles (anchor roots and supply nutrients) and humus/organic matter (holds moisture and releases nutrients); air and water in the pores support root respiration and nutrient uptake.', NULL, 'text', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_005_b', 'q_sci_2024_2_005', 'b', 'Explain why loamy soil is considered best for crop production.', 3, 'Loam balances sand, silt and clay with humus, so it drains well yet retains enough water and nutrients, and it is easily worked by roots and tools.', NULL, 'text', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_005_c', 'q_sci_2024_2_005', 'c', 'Describe how adding compost improves the soil.', 3, 'Compost adds humus, which improves soil structure and water retention and releases nitrogen, phosphorus and potassium slowly as it decomposes.', NULL, 'text', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_005_d', 'q_sci_2024_2_005', 'd', 'State one soil conservation practice the farmer can use on sloping land and explain how it works.', 3, 'Contour ploughing (or terracing): ploughing across the slope slows run-off, reducing soil erosion and keeping nutrients in place.', NULL, 'text', 4);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_006_a', 'q_sci_2024_2_006', 'a', 'Name the organism that causes malaria and the vector that transmits it.', 3, 'Malaria is caused by Plasmodium parasites and transmitted by the female Anopheles mosquito.', NULL, 'text', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_006_b', 'q_sci_2024_2_006', 'b', 'State two symptoms of malaria.', 3, 'Any two of: high fever with chills, headache, sweating, nausea/vomiting, body weakness.', NULL, 'text', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_006_c', 'q_sci_2024_2_006', 'c', 'Describe two measures used to prevent the spread of malaria.', 3, 'Sleeping under insecticide-treated mosquito nets, and clearing stagnant water or spraying insecticides to kill mosquitoes and larvae.', NULL, 'text', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_sci_2024_2_006_d', 'q_sci_2024_2_006', 'd', 'Explain why draining stagnant water helps to control malaria.', 3, 'Mosquitoes breed in stagnant water; removing it destroys breeding sites, so fewer adult mosquitoes emerge to transmit the parasite.', NULL, 'text', 4);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-paper2-theory-002', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://waecgh.org/', 0, 1 FROM questions WHERE id IN ('q_sci_2024_2_001', 'q_sci_2024_2_002', 'q_sci_2024_2_003', 'q_sci_2024_2_004', 'q_sci_2024_2_005', 'q_sci_2024_2_006', 'q_sci_2024_2_007', 'q_sci_2024_2_008');
