INSERT INTO _migration_365_guard(valid) SELECT CASE WHEN EXISTS (SELECT 1 FROM past_papers p WHERE p.id = 'pp_wassce_sci_2024_2' AND p.id IS 'pp_wassce_sci_2024_2' AND p.exam_type_id IS 'exam_wassce' AND p.subject_id IS 'subj_wassce_int_science' AND p.paper_type_id IS 'paper_wassce_2' AND p.year IS '2024' AND p.month IS 'May-June' AND p.series IS 'WASSCE' AND p.title IS 'Integrated Science Paper 2 (2024)' AND p.description IS 'WASSCE Integrated Science theory practice: compulsory structured questions and essays across the syllabus strands.' AND p.total_questions IS '8' AND p.total_marks IS '100' AND p.time_allowed IS '105' AND p.instructions IS 'Answer ALL the questions in this paper.' AND p.is_complete IS '1' AND p.is_premium IS '0' AND p.source_url IS NULL) AND (SELECT COUNT(*) FROM questions WHERE id IN ('q_sci_2024_2_001', 'q_sci_2024_2_002', 'q_sci_2024_2_003', 'q_sci_2024_2_004', 'q_sci_2024_2_005', 'q_sci_2024_2_006', 'q_sci_2024_2_007', 'q_sci_2024_2_008')) = 8 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_sci_2024_2_001', 'q_sci_2024_2_002', 'q_sci_2024_2_003', 'q_sci_2024_2_004', 'q_sci_2024_2_005', 'q_sci_2024_2_006', 'q_sci_2024_2_007', 'q_sci_2024_2_008') AND r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM topics WHERE id IN ('topic_wassce_p2_sci_eco', 'topic_wassce_p2_sci_mat', 'topic_wassce_p2_sci_enr', 'topic_wassce_p2_sci_bio', 'topic_wassce_p2_sci_agr', 'topic_wassce_p2_sci_hlt', 'topic_wassce_p2_sci_wst', 'topic_wassce_p2_sci_env')) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id WHERE q.id IN ('q_sci_2024_2_001', 'q_sci_2024_2_002', 'q_sci_2024_2_003', 'q_sci_2024_2_004', 'q_sci_2024_2_005', 'q_sci_2024_2_006', 'q_sci_2024_2_007', 'q_sci_2024_2_008')) = 8 AND (SELECT COUNT(*) FROM essay_questions WHERE question_id IN ('q_sci_2024_2_007', 'q_sci_2024_2_008')) = 2 AND (SELECT COUNT(*) FROM structured_question_parts WHERE question_id IN ('q_sci_2024_2_001', 'q_sci_2024_2_002', 'q_sci_2024_2_003', 'q_sci_2024_2_004', 'q_sci_2024_2_005', 'q_sci_2024_2_006')) = 24 THEN 1 ELSE 0 END;
